<?php
declare(strict_types=1);
require __DIR__.'/../config/auth.php'; require __DIR__.'/../config/database.php'; require __DIR__.'/../config/listing_integrity.php';
require_admin(); if(empty($_SESSION['admin_csrf']))$_SESSION['admin_csrf']=bin2hex(random_bytes(32));$message='';
if($_SERVER['REQUEST_METHOD']==='POST'&&hash_equals($_SESSION['admin_csrf'],(string)($_POST['csrf']??''))){$id=(int)($_POST['alert_id']??0);$action=$_POST['action']??'';if($id&&in_array($action,['read','dismiss'],true)){db()->prepare('UPDATE admin_alerts SET is_read=true WHERE id=?')->execute([$id]);record_audit_event('admin',null,'alert.'.$action,'admin_alert',$id);$message='Uyarı güncellendi.';}}
$alerts=db()->query('SELECT a.*,s.company_name FROM admin_alerts a LEFT JOIN suppliers s ON s.id=a.supplier_id ORDER BY a.is_read,a.created_at DESC LIMIT 200')->fetchAll();$logs=db()->query('SELECT * FROM audit_logs ORDER BY created_at DESC LIMIT 50')->fetchAll();
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Uyarı merkezi | NEXUS Admin</title><style>body{margin:0;background:#f7f7f2;color:#10211f;font-family:Arial}.w{width:min(1050px,calc(100% - 32px));margin:40px auto}.c{background:#fff;border:1px solid #e1e5de;padding:18px;margin:15px 0}.unread{border-left:5px solid #e85f42}.meta{color:#64716d;font-size:13px}.actions{display:flex;gap:8px;margin-top:10px}button{padding:8px 10px;border:1px solid #d8ded8;background:#fff}.ok{background:#e6f8c7;padding:10px}.log{font-size:13px;padding:9px 0;border-top:1px solid #eee}</style></head><body><main class="w"><a href="/nexustraveltech/admin/">← Panele dön</a><h1>Operasyon uyarı merkezi</h1><?php if($message):?><p class="ok"><?=htmlspecialchars($message)?></p><?php endif;?><section><h2>Açık ve geçmiş uyarılar</h2><?php foreach($alerts as $a):?><article class="c <?=!$a['is_read']?'unread':''?>"><b><?=htmlspecialchars($a['title'])?></b><p><?=nl2br(htmlspecialchars($a['body']))?></p><span class="meta"><?=htmlspecialchars($a['alert_type'])?> · <?=htmlspecialchars($a['company_name']?:'Platform') ?> · <?=htmlspecialchars($a['created_at'])?></span><?php if(!$a['is_read']):?><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['admin_csrf'])?>"><input type="hidden" name="alert_id" value="<?= (int)$a['id']?>"><button name="action" value="read">Okundu</button><button name="action" value="dismiss">Kapat</button></form><?php endif;?></article><?php endforeach;?></section><section class="c"><h2>Son denetim kayıtları</h2><?php foreach($logs as $l):?><div class="log"><b><?=htmlspecialchars($l['action'])?></b> · <?=htmlspecialchars($l['entity_type']) ?> #<?=htmlspecialchars((string)$l['entity_id'])?> <span class="meta"><?=htmlspecialchars($l['created_at'])?></span></div><?php endforeach;?></section></main><?php require_once __DIR__.'/../config/ai_widget.php'; ai_widget('/nexustraveltech/admin/ai-chat','admin_csrf'); ?></body></html>
